  "  把粮和人留给他搜，就永远熬不走他——「熬」是藏净换来的，不是等来的。",
  "一条常被误解的事：**代价簿与勋记无关**。代价簿只记损失、永不回落，也永不折成任何收益；",
  "  它不参与评级，也不会因为你打得好而减少。它是账，不是分。",
