    "扑空衰减：摸到村 2 格内却一无所获的纵队每支 -1 池（每回合至多 -2）。",
    "  **已经装了车（抢到粮或拉到人）的队伍不算扑空**——把东西留给敌人搜，就别指望把他熬走。",
